$(document).ready(function() {

	function showPopUp(popUpType, type, msg, status, position, timer) {

		/** trigger swal.fire method */

		if(popUpType=='position') {

			Swal.fire({
				position: position,
				type: status,
				title: msg,
				showConfirmButton: false,
				timer: timer
			})

		} else {
			
			Swal.fire(
				type,
				msg,
				status
			);

		}

	}

	/* Submit Category */

	$('#submitForm').click(function(e) {
		
		var data = new FormData(document.getElementById('formData'));

		$.ajax({
			type: 'POST',
			data: data,
			processData: false,
			contentType: false,
			dataType: 'JSON',
			success: function(data) {
				if(data.status==200) {
					var success = 'success';
					$('#formData')[0].reset();
				} else {
					var success = 'error';
				}

				Swal.fire({
					position: 'top-end',
					type: success,
					title: data.msg,
					showConfirmButton: false,
					timer: 1500
				})

				if(data.status!=206) {
					setTimeout(function(){
						location.reload();
					}, 1500)
				}
			},
			error: function(data) {
				console.log(data);
			}
		})
		e.preventDefault();
	});

	$('.addSeat').click(function(e) {

		var divData=$(this).attr('id');

		var string=divData.split('_');

		$.ajax({
			url: window.location.origin + '/api/updateElection.php',
			type: 'GET',
			dataType: 'JSON',
			data: {
				party : string[0],
				result : string[1],
				action : 'add'
			},
			success: function(data) {

				if(data.status==200) {
					var success = 'success';
				} else {
					var success = 'error';
				}

				Swal.fire({
					position: 'top-end',
					type: success,
					title: data.msg,
					showConfirmButton: false,
					timer: 1500
				})

				if(data.status!=206) {
					setTimeout(function(){
						location.reload();
					}, 1500)
				}
			},

			error: function(data) {
				console.log(data);
			}
		})

		e.preventDefault();
	})

	$('.removeSeat').click(function(e) {

		var divData=$(this).attr('id');

		var string=divData.split('_');

		$.ajax({
			url: window.location.origin + '/api/updateElection.php',
			type: 'GET',
			dataType: 'JSON',
			data: {
				party : string[0],
				result : string[1],
				action : 'remove',
			},
			success: function(data) {

				if(data.status==200) {
					var success = 'success';
				} else {
					var success = 'error';
				}

				Swal.fire({
					position: 'top-end',
					type: success,
					title: data.msg,
					showConfirmButton: false,
					timer: 1500
				})

				if(data.status!=206) {
					setTimeout(function(){
						location.reload();
					}, 1500)
				}
			},

			error: function(data) {
				console.log(data);
			}
		})

		e.preventDefault();
	})


});